import Foundation

enum GlossaryData {
    static let terms: [GlossaryTerm] = [
        GlossaryTerm(term: "Neat", definition: "A spirit served with no ice, no dilution, and no mixer — straight from the bottle into the glass."),
        GlossaryTerm(term: "Up", definition: "A drink shaken or stirred with ice, then strained into a stemmed glass with no ice in it, like a Martini."),
        GlossaryTerm(term: "On the Rocks", definition: "A drink served over ice cubes in the glass."),
        GlossaryTerm(term: "Muddle", definition: "To press and gently crush fruit, herbs, or sugar with a muddler to release juice, oils, and aroma."),
        GlossaryTerm(term: "Jigger", definition: "A two-sided measuring tool used to pour precise, consistent amounts of liquid."),
        GlossaryTerm(term: "Double Strain", definition: "Straining a shaken drink through both the shaker's built-in strainer and a fine mesh strainer to remove small ice shards or pulp."),
        GlossaryTerm(term: "Dash", definition: "A small, quick shake of bitters or another strong flavoring, roughly 1 ml."),
        GlossaryTerm(term: "Rinse", definition: "Coating the inside of a glass with a small amount of spirit (often absinthe), then discarding the excess before building the drink."),
        GlossaryTerm(term: "Float", definition: "Gently pouring a liquid, often over the back of a bar spoon, so it sits on top of the drink rather than mixing in."),
        GlossaryTerm(term: "Twist / Zest", definition: "A strip of citrus peel expressed over a drink to release aromatic oils, then used as garnish."),
        GlossaryTerm(term: "Simple Syrup", definition: "A 1:1 (or sometimes 2:1) mixture of sugar dissolved in water, used to sweeten cocktails."),
        GlossaryTerm(term: "Orgeat", definition: "A sweet, almond-based syrup used in tiki cocktails like the Mai Tai."),
        GlossaryTerm(term: "Triple Sec", definition: "An orange-flavored liqueur used in drinks like the Margarita and Cosmopolitan."),
        GlossaryTerm(term: "Vermouth", definition: "A fortified, aromatized wine — dry or sweet — used as a modifier in drinks like the Martini and Manhattan."),
        GlossaryTerm(term: "Bitters", definition: "A highly concentrated, aromatic flavoring made from botanicals, used in small dashes to add complexity."),
        GlossaryTerm(term: "Proof", definition: "A measure of alcohol strength; in the US, proof is double the alcohol-by-volume percentage (e.g., 80 proof = 40% ABV)."),
        GlossaryTerm(term: "Free Pour", definition: "Pouring spirits directly from the bottle without a jigger, judged by counting seconds, once practiced enough to stay accurate."),
        GlossaryTerm(term: "Well Drink", definition: "A cocktail made with the bar's standard, unspecified 'house' spirits rather than a named brand."),
        GlossaryTerm(term: "Call Drink", definition: "A cocktail where the guest specifically names ('calls') the brand of spirit they want used."),
        GlossaryTerm(term: "Top Shelf", definition: "Premium, higher-end spirits, traditionally displayed on the top shelf behind the bar."),
        GlossaryTerm(term: "Mixology", definition: "The art and craft of designing and preparing cocktails."),
        GlossaryTerm(term: "Aperitif", definition: "A drink served before a meal to stimulate the appetite, often light and bitter, like an Aperol Spritz."),
        GlossaryTerm(term: "Digestif", definition: "A drink served after a meal, believed to aid digestion, often richer or herbal, like an amaro."),
        GlossaryTerm(term: "Mocktail", definition: "A cocktail-style drink made without any alcohol."),
        GlossaryTerm(term: "Speakeasy", definition: "Historically, an illicit bar during Prohibition; today, a style of intimate, often hidden cocktail bar."),
        GlossaryTerm(term: "Highball", definition: "A tall drink made of a spirit and a larger volume of mixer, served over ice in a tall glass."),
        GlossaryTerm(term: "Sour", definition: "A cocktail family built from a base spirit, citrus juice, and a sweetener."),
        GlossaryTerm(term: "Shaken", definition: "The technique of combining ingredients in a shaker with ice, then shaking hard to chill, dilute, and aerate."),
        GlossaryTerm(term: "Stirred", definition: "The technique of mixing ingredients with ice in a mixing glass using a bar spoon, for a clear, silky result."),
        GlossaryTerm(term: "Build", definition: "Assembling a drink directly in its serving glass, usually over ice, with minimal extra mixing.")
    ]
}
